"""Minimal YAML renderer (standard library only)."""

from plugins import PluginError, Renderer, register


def _yaml_value(v) -> str:
    """Return a YAML-safe scalar string for *v*."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return str(v)
    # Treat everything else as a string.
    s = str(v)
    # Quote if the value could be misinterpreted.
    if s == "" or s in ("null", "true", "false", "yes", "no", "on", "off"):
        return f'"{s}"'
    if any(c in s for c in ":{}[]&*?|->!%@`,#"):
        return f'"{s}"'
    if s.startswith(('"', "'", "{", "[", "(", ">", "|", "&", "*")):
        return f'"{s}"'
    return s


def _yaml_row(row: dict) -> str:
    """Render a single dict as YAML key-value lines."""
    lines = []
    for k, v in row.items():
        lines.append(f"{k}: {_yaml_value(v)}")
    return "\n".join(lines)


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return "\n".join(_yaml_row(r) for r in rows)

